const fs = require('fs');

const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
const n = BigInt(input[0]);
const k = BigInt(input[1]);

if (k <= n + 1n) {
    console.log((k - 1n) / 2n);
} else if (k >= n * 2n) {
    console.log(0);
} else {
    console.log(n - k / 2n);
}

